import { StrictMode, useEffect, useMemo, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { Activity, ArrowRight, BarChart3, BookOpen, Check, ChevronDown, CircleHelp, CloudRain, Database, Download, Earth, Expand, FileText, Filter, Gauge, Globe2, Layers3, LineChart, Map as MapIcon, Menu, Minimize2, Moon, Network, PanelLeft, Play, RotateCcw, Satellite, Search, Settings, ShieldCheck, Sparkles, Sprout, Sun, Table2, TrendingDown, TrendingUp, X, ZoomIn, ZoomOut } from 'lucide-react';
import './styles.css';
import './polish.css';
import { ApiStatus, DatasetRecord, ProvinceRecord, checkApi, loadApiCatalog, loadRegionGeoJSON, mapPreviewUrl, runAnalysis, searchCatalog } from './api';

type Page='overview'|'explore'|'lab'|'data'|'investigations'|'methodology'|'settings'|'terms';
type Settings={language:'pt'|'en';map:'Relief'|'Satellite'|'Heat'|'Contour';chart:'Linha'|'Barras'|'Dispersão'|'Área'|'Histograma'|'Circular';compact:boolean};
type SettingsTab='general'|'visual'|'science'|'accessibility';
const initialSettings:Settings={language:'pt',map:'Relief',chart:'Linha',compact:false};
const labels={pt:{overview:'Visão geral',explore:'Explorar a Terra',lab:'Trend Lab',data:'Biblioteca de dados',investigations:'Investigações',methodology:'Metodologia',settings:'Configurações',newStudy:'Nova investigação',run:'Executar análise',save:'Guardar preferências'},en:{overview:'Overview',explore:'Explore Earth',lab:'Trend Lab',data:'Data library',investigations:'Investigations',methodology:'Methodology',settings:'Settings',newStudy:'New investigation',run:'Run analysis',save:'Save preferences'}};
const angolaProvinces=['Bengo','Benguela','Bié','Cabinda','Cuando','Cuanza Norte','Cuanza Sul','Cubango','Cunene','Huambo','Huíla','Icolo e Bengo','Luanda','Lunda Norte','Lunda Sul','Malanje','Moxico','Moxico Leste','Namibe','Uíge','Zaire'];
const regionSlug=(name:string)=>name==='Angola — todas as províncias'?'angola':name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/,\s*angola$/,'').trim().replace(/\s+/g,'_');

function App(){
 const [page,setPage]=useState<Page>('overview'); const [mobile,setMobile]=useState(false); const [apiStatus,setApiStatus]=useState<ApiStatus>('loading'); const [datasets,setDatasets]=useState<DatasetRecord[]>([]); const [provinces,setProvinces]=useState<ProvinceRecord[]>([]); const [catalogLoading,setCatalogLoading]=useState(true); const [catalogError,setCatalogError]=useState(''); const [settingsTab,setSettingsTab]=useState<SettingsTab>('general'); const [cookies,setCookies]=useState(()=>localStorage.getItem('earthtrend-cookie-consent')==='accepted'); const [settings,setSettings]=useState<Settings>(()=>{try{return {...initialSettings,...JSON.parse(localStorage.getItem('earthtrend-react-settings')||'{}')}}catch{return initialSettings}}); const [region,setRegion]=useState('Angola — todas as províncias'); const [variable,setVariable]=useState('Precipitação'); const [period,setPeriod]=useState('2000–2025'); const [selectedDatasetId,setSelectedDatasetId]=useState('gpm_imerg_monthly'); const [periodMode,setPeriodMode]=useState<'annual'|'five_year'|'decade'>('annual'); const [ran,setRan]=useState(false); const t=labels[settings.language];
 const updateSettings=(next:Partial<Settings>)=>{const value={...settings,...next};setSettings(value);localStorage.setItem('earthtrend-react-settings',JSON.stringify(value))};
 const refreshCatalog=()=>{setCatalogLoading(true);setCatalogError('');loadApiCatalog().then(catalog=>{setDatasets(catalog.datasets);setProvinces(catalog.provinces)}).catch(error=>{setCatalogError(error instanceof Error?error.message:'Não foi possível carregar os modelos.');}).finally(()=>setCatalogLoading(false));};
 useEffect(()=>{let active=true;checkApi().then(connected=>{if(active)setApiStatus(connected?'connected':'offline')});refreshCatalog();return()=>{active=false}},[]);
 return <div className={settings.compact?'app compact':'app'}><aside className={mobile?'sidebar mobile-open':'sidebar'}><div className="brand"><div className="brand-icon"><Earth size={21}/></div><div><b>EarthTrend<span>AI</span></b><small>EARTH SYSTEM INTELLIGENCE</small></div><button className="mobile-close" onClick={()=>setMobile(false)}><X size={18}/></button></div><div className="workspace-label">WORKSPACE</div><nav>{([['overview',PanelLeft, t.overview],['explore',Globe2,t.explore],['lab',Activity,t.lab],['data',Database,t.data],['investigations',FileText,t.investigations],['methodology',BookOpen,t.methodology]] as const).map(([id,Icon,name])=><button className={page===id?'nav-item active':'nav-item'} onClick={()=>{setPage(id);setMobile(false)}} key={id}><Icon size={17}/><span>{name}</span>{id==='lab'&&<i>LIVE</i>}</button>)}</nav><div className="sidebar-foot"><ShieldCheck size={17}/><div><b>Integridade científica</b><span>Resultados demonstrativos são claramente identificados.</span><button className="legal-link" onClick={()=>{setPage('terms');setMobile(false)}}>Termos e condições</button></div></div></aside><main><header className="topbar"><button className="menu-btn" onClick={()=>setMobile(true)}><Menu size={20}/></button><div className="crumb"><span>EarthTrend AI</span><ChevronDown size={14}/><b>{page==='overview'?t.overview:page==='lab'?t.lab:page==='settings'?t.settings:page==='terms'?'Termos e condições':'Earth system workspace'}</b></div><div className="top-actions"><span className={apiStatus==='connected'?'demo-pill api-live':'demo-pill'}><span/> {apiStatus==='connected'?'API CONNECTED':apiStatus==='loading'?'CONNECTING…':'DEMO DATASET'}</span><button className="icon-btn" title={t.settings} onClick={()=>setPage('settings')}><Settings size={19}/></button></div></header><div className="content">{page==='overview'&&<Overview setPage={setPage} t={t}/>} {page==='explore'&&<Explore region={region} setRegion={setRegion} variable={variable} setVariable={setVariable} period={period} setPeriod={setPeriod} selectedDatasetId={selectedDatasetId} setSelectedDatasetId={setSelectedDatasetId} periodMode={periodMode} setPeriodMode={setPeriodMode} datasets={datasets} setPage={setPage} t={t} provinces={provinces} catalogLoading={catalogLoading} catalogError={catalogError} onRetryCatalog={refreshCatalog}/>}  {page==='lab'&&<Lab settings={settings} updateSettings={updateSettings} region={region} variable={variable} period={period} selectedDatasetId={selectedDatasetId} periodMode={periodMode} datasets={datasets} ran={ran} setRan={setRan} t={t}/>} {page==='data'&&<DataPage t={t} datasets={datasets}/>} {page==='investigations'&&<Investigations t={t}/>} {page==='methodology'&&<Methodology t={t}/>} {page==='settings'&&<SettingsPage settings={settings} updateSettings={updateSettings} t={t} tab={settingsTab} setTab={setSettingsTab}/>} {page==='terms'&&<TermsPage setPage={setPage}/>}</div></main>{!cookies&&<CookieNotice onAccept={()=>{localStorage.setItem('earthtrend-cookie-consent','accepted');setCookies(true)}} onTerms={()=>setPage('terms')}/>}</div>
}
function PageHead({eyebrow,title,description,action}:{eyebrow:string;title:React.ReactNode;description:string;action?:React.ReactNode}){return <div className="page-head"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{action}</div>}
function Overview({setPage,t}:{setPage:(p:Page)=>void;t:any}){return <><PageHead eyebrow="NASA SPACE APPS CHALLENGE · LUANDA" title={<>Leia o território.<br/><em>Entenda a mudança.</em></>} description="Explora padrões ambientais e acompanha as mudanças do território através de dados de observação da Terra." action={<button className="button secondary" onClick={()=>setPage('settings')}><Settings size={16}/> Personalizar</button>}/><section className="hero"><div className="hero-orbit orbit-one"/><div className="hero-orbit orbit-two"/><div className="hero-content"><span className="hero-kicker"><Earth size={14}/> OBSERVAÇÃO DO SISTEMA TERRESTRE</span><h2>Observar a Terra. Compreender as suas mudanças.</h2><p>Escolhe uma região, acompanha uma variável e vê o que os dados permitem afirmar — e o que ainda precisa de ser investigado.</p><button className="button lime" onClick={()=>setPage('explore')}>{t.newStudy}<ArrowRight size={16}/></button></div><div className="hero-aside"><span>ESTADO DA ANÁLISE</span><strong>PRONTO</strong><small>À espera de dados reais</small></div></section><div className="section-heading"><div><span className="eyebrow">ÁREA DE TRABALHO</span><h2>Sem resultados carregados</h2></div><span className="status-chip">Workspace pronto</span></div><div className="home-grid"><div className="panel workflow"><PanelTitle icon={Network} title="Percurso de investigação" tag="FLUXO"/><div className="workflow-line">{['Enquadrar','Selecionar dados','Validar','Estimar','Interpretar'].map((x,i)=><div className="workflow-step" key={x}><span>{String(i+1).padStart(2,'0')}</span><b>{x}</b>{i<4&&<i/>}</div>)}</div><p className="panel-note">Os resultados só aparecem depois de o backend devolver uma série temporal válida.</p></div><div className="panel quick"><PanelTitle icon={Gauge} title="Começar uma investigação"/><div className="quick-row"><div><span>Primeiro caso de uso</span><b>Precipitação — Angola</b></div><CloudRain size={23}/></div><button className="button dark full" onClick={()=>setPage('explore')}>Começar agora <ArrowRight size={15}/></button></div></div><div className="angola-card"><div className="angola-map-shell"><GeoLayer regionId="angola"/><div className="map-base-label">ANGOLA · MAPA-BASE</div></div><div><span className="eyebrow">PONTO DE PARTIDA</span><h2>Angola em foco</h2><p>A primeira análise usa precipitação mensal NASA GPM IMERG. A aplicação distingue dados observados, resultados estatísticos e limitações.</p></div><div className="angola-facts"><span><b>Primeira variável</b>Precipitação</span><span><b>Fonte ligada</b>NASA GPM IMERG</span><span><b>Motor estatístico</b>Mann–Kendall + Sen</span><span><b>Mapa raster</b>Ainda não disponível neste modo</span></div></div></>}
function GeoLayer({regionId='angola',overlay=false}:{regionId?:string;overlay?:boolean}){
 const [geo,setGeo]=useState<any>(null);
 useEffect(()=>{let alive=true;loadRegionGeoJSON(regionId).then(g=>{if(alive)setGeo(g)}).catch(()=>{if(alive)setGeo(null)});return()=>{alive=false}},[regionId]);
 const rings=useMemo(()=>{const out:number[][][]=[];const collect=(coords:any)=>{if(!Array.isArray(coords))return;if(coords.length>=2&&typeof coords[0]==='number'&&typeof coords[1]==='number'){return}if(coords.length&&Array.isArray(coords[0])&&typeof coords[0][0]==='number'){out.push(coords as number[][]);return}coords.forEach(collect)};const walk=(g:any)=>{if(!g)return;if(g.type==='FeatureCollection')g.features?.forEach((f:any)=>walk(f.geometry));else if(g.type==='Feature')walk(g.geometry);else if(g.type==='Polygon')g.coordinates?.forEach(collect);else if(g.type==='MultiPolygon')g.coordinates?.forEach((poly:any)=>poly.forEach(collect));};walk(geo);return out;},[geo]);
 const all=rings.flat();if(!all.length)return <svg className="geo-layer geo-fallback" viewBox="0 0 320 300" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Mapa-base esquemático de Angola, disponível sem ligação à API"><defs><pattern id="map-grid" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M24 0H0V24" fill="none" stroke="#cbd8cf" strokeWidth=".5" opacity=".45"/></pattern></defs><rect width="320" height="300" fill="url(#map-grid)"/><path d="M82 25 L111 31 L137 52 L158 54 L170 71 L188 78 L193 104 L215 117 L208 143 L222 160 L215 180 L198 191 L185 213 L173 233 L160 255 L146 271 L129 265 L120 247 L107 232 L95 213 L78 198 L68 178 L58 160 L50 140 L45 121 L54 102 L61 82 L68 63 L74 45 Z" fill="#b8d0bf" stroke="#567c63" strokeWidth="2" strokeLinejoin="round"/><path d="M22 39 L46 36 L54 45 L51 57 L37 61 L24 54 Z" fill="#b8d0bf" stroke="#567c63" strokeWidth="2" strokeLinejoin="round"/><path d="M84 47 L102 76 L119 91 M67 91 L97 105 L123 115 M55 129 L91 142 L115 147 M78 177 L107 174 L135 181 M95 213 L124 206 L146 218 M120 247 L145 242" fill="none" stroke="#eaf4ed" strokeWidth="1.7" strokeLinejoin="round" opacity=".9"/><text x="160" y="285" textAnchor="middle" fontSize="10" letterSpacing="2.2" fill="#567463" fontWeight="700">ANGOLA · MAPA-BASE</text><text x="19" y="22" fontSize="8" fill="#789084" letterSpacing="1">CABINDA</text><text x="12" y="158" fontSize="8" fill="#789084" letterSpacing="1" transform="rotate(-90 12 158)">ATLÂNTICO</text></svg>;
 const xs=all.map(p=>p[0]),ys=all.map(p=>p[1]);const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);const w=maxX-minX||1,h=maxY-minY||1;
 const paths=rings.map(r=>r.map((p,i)=>((i?'L':'M')+((p[0]-minX)/w*100).toFixed(2)+','+(100-(p[1]-minY)/h*100).toFixed(2))).join(' ')+' Z');
 return <svg className={overlay?'geo-layer geo-overlay':'geo-layer'} viewBox="0 0 100 100" preserveAspectRatio="xMidYMid meet" aria-label="Mapa vectorial de Angola e limites provinciais">{paths.map((d,i)=><path key={i} d={d} className={overlay?'geo-outline':'geo-shape'}/>)}</svg>
}
function Metric({icon:Icon,label,value,note}:{icon:any;label:string;value:string;note:string}){return <div className="metric"><div className="metric-icon"><Icon size={17}/></div><span>{label}</span><strong>{value}</strong><small>{note}</small></div>}
function PanelTitle({icon:Icon,title,tag}:{icon:any;title:string;tag?:string}){return <div className="panel-title"><div className="panel-title-name"><Icon size={17}/><h3>{title}</h3></div>{tag&&<span className="tag">{tag}</span>}</div>}
function Explore({region,setRegion,variable,setVariable,period,setPeriod,selectedDatasetId,setSelectedDatasetId,periodMode,setPeriodMode,datasets,setPage,t,provinces,catalogLoading,catalogError,onRetryCatalog}:{region:string;setRegion:(x:string)=>void;variable:string;setVariable:(x:string)=>void;period:string;setPeriod:(x:string)=>void;selectedDatasetId:string;setSelectedDatasetId:(x:string)=>void;periodMode:'annual'|'five_year'|'decade';setPeriodMode:(x:'annual'|'five_year'|'decade')=>void;datasets:DatasetRecord[];setPage:(p:Page)=>void;t:any;provinces:ProvinceRecord[];catalogLoading:boolean;catalogError:string;onRetryCatalog:()=>void}){return <><PageHead eyebrow="PASSO 01 · FRAME THE QUESTION" title="Um lugar é o começo de toda pergunta ambiental." description="Define o contexto espacial, a variável e o período antes de executar uma análise." action={<div className="step-counter">01 <span>/</span> 03</div>}/><div className="stepper"><b className="current">01 Região</b><b>02 Análise</b><b>03 Relatório</b></div><div className="study-grid"><div className="panel form-panel"><PanelTitle icon={Filter} title="Study configuration" tag="REQUIRED"/><Field label="Região de estudo"><select value={region} onChange={e=>setRegion(e.target.value)}><option>Angola — todas as províncias</option>{provinces.length?provinces.map(province=><option key={province.id}>{province.name}, Angola</option>):angolaProvinces.map(province=><option key={province}>{province}, Angola</option>)}</select></Field><Field label="Modelo / conjunto de dados"><select value={datasets.some(d=>d.id===selectedDatasetId)?selectedDatasetId:''} onChange={e=>{const id=e.target.value;setSelectedDatasetId(id);const d=datasets.find(x=>x.id===id);if(d?.coverage_start&&d?.coverage_end){const lo=Number(d.coverage_start.slice(0,4));const hi=Number(d.coverage_end.slice(0,4));const [a,b]=period.split(/[–-]/).map(Number);setPeriod(`${Math.max(lo,Math.min(a,hi))}–${Math.max(lo,Math.min(b,hi))}`)}}}>{!datasets.length&&<option value="">{catalogLoading?'A carregar catálogo de modelos…':'Catálogo de modelos indisponível'}</option>}{datasets.map(d=><option key={d.id} value={d.id} disabled={d.status!=="available"||!d.ready}>{d.name}{d.status!=="available"?" — em preparação":!d.ready?" — indisponível":""}</option>)}</select>{catalogLoading&&<small className="field-hint"><span className="loading-dots" aria-label="A carregar"><i/><i/><i/></span> A sincronizar o catálogo com o servidor…</small>}{catalogError&&<small className="field-hint" role="alert">{catalogError} <button type="button" className="text-button" onClick={onRetryCatalog}>Tentar novamente</button></small>}<small className="field-hint">Os modelos ainda não ligados aparecem bloqueados. A escolha determina a variável e a cobertura temporal.</small></Field><Field label="Variável ambiental"><input value={datasets.find(d=>d.id===selectedDatasetId)?.variable_label||variable} readOnly/></Field><div className="two-fields"><Field label="Ano inicial"><select value={period.split(/[–-]/)[0]} onChange={e=>setPeriod(`${e.target.value}–${period.split(/[–-]/)[1]||e.target.value}`)}>{Array.from({length:29},(_,i)=>1998+i).map(y=>{const d=datasets.find(x=>x.id===selectedDatasetId);const min=Number((d?.coverage_start||"2000-01").slice(0,4));const max=Number((d?.coverage_end||"2025-09").slice(0,4));return <option key={y} value={y} disabled={y<min||y>max}>{y}{y<min||y>max?" — bloqueado":y===min?" — parcial":y===max?" — parcial":""}</option>})}</select></Field><Field label="Ano final"><select value={period.split(/[–-]/)[1]||period.split(/[–-]/)[0]} onChange={e=>setPeriod(`${period.split(/[–-]/)[0]}–${e.target.value}`)}>{Array.from({length:29},(_,i)=>1998+i).map(y=>{const d=datasets.find(x=>x.id===selectedDatasetId);const min=Number((d?.coverage_start||"2000-01").slice(0,4));const max=Number((d?.coverage_end||"2025-09").slice(0,4));return <option key={y} value={y} disabled={y<min||y>max}>{y}{y<min||y>max?" — bloqueado":y===min?" — parcial":y===max?" — parcial":""}</option>})}</select></Field></div><Field label="Visualização temporal"><select value={periodMode} onChange={e=>setPeriodMode(e.target.value as "annual"|"five_year"|"decade")}><option value="annual">Anual — cada ano individual</option><option value="five_year">Blocos de 5 anos — médias comparáveis</option><option value="decade">Décadas — médias comparáveis</option></select></Field><p className="field-hint">{datasets.find(d=>d.id===selectedDatasetId)?.coverage_note||"A cobertura depende do modelo selecionado."} Os anos fora da cobertura ficam bloqueados. Os anos parciais são identificados e podem ser excluídos se não tiverem 12 meses completos.</p><Field label="Pergunta científica"><textarea defaultValue="A precipitação apresenta uma tendência persistente nesta região?"/></Field><p className="field-hint">A disponibilidade dos dados depende da fonte e do período selecionado.</p><button className="button dark full" onClick={()=>setPage('lab')}>Continuar para o Trend Lab <ArrowRight size={16}/></button></div></div></>}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="field"><span>{label}</span>{children}</label>}
function MapPreview({type}:{type:string}){return <div className="map-preview" role="status"><div className="map-label"><b>Camada espacial em preparação</b><span>A visualização cartográfica será apresentada quando a análise devolver dados geográficos.</span></div></div>}
function MapPanel({src,dataset,region,period}:{src:string;dataset?:DatasetRecord;region:string;period:string}){
 const [zoom,setZoom]=useState(1); const [expanded,setExpanded]=useState(false); const [loaded,setLoaded]=useState(false); const [failed,setFailed]=useState(false);
 useEffect(()=>{setLoaded(false);setFailed(false);setZoom(1)},[src]);
 const range=dataset?.map_range;
 return <section className={expanded?'panel raster-panel raster-expanded':'panel raster-panel'} aria-label="Mapa raster ambiental">
  <div className="raster-heading"><div><PanelTitle icon={MapIcon} title="Distribuição espacial da variável" tag="RASTER REAL"/><p className="panel-note">Camada gerada pelo Google Earth Engine a partir do produto seleccionado.</p></div></div>
  <div className="raster-controls">
   <button type="button" aria-label="Reduzir mapa" title="Reduzir" disabled={zoom<=.7} onClick={()=>setZoom(v=>Math.max(.7,Number((v-.15).toFixed(2))))}><ZoomOut size={16}/></button><span>{Math.round(zoom*100)}%</span>
   <button type="button" aria-label="Ampliar mapa" title="Ampliar" disabled={zoom>=2} onClick={()=>setZoom(v=>Math.min(2,Number((v+.15).toFixed(2))))}><ZoomIn size={16}/></button>
   <button type="button" aria-label={expanded?'Recolher mapa':'Expandir mapa'} title={expanded?'Recolher':'Expandir'} onClick={()=>setExpanded(v=>!v)}>{expanded?<Minimize2 size={16}/>:<Expand size={16}/>}</button>
  </div>
  <div className="raster-image-frame">
   <GeoLayer regionId={regionSlug(region)} overlay/>
   {!loaded&&!failed&&<div className="raster-state">A gerar e carregar a camada raster NASA…</div>}
   {failed&&<div className="raster-state raster-error">Não foi possível carregar o mapa. Verifica a disponibilidade do Earth Engine e tenta novamente após o intervalo de espera.</div>}
   <img src={src} alt={`Raster ambiental de ${dataset?.name||'variável NASA'} em ${region}, período ${period}. A imagem representa a média temporal das imagens disponíveis.`} onLoad={()=>setLoaded(true)} onError={()=>setFailed(true)} style={{width:(zoom*100)+'%',maxWidth:'none',display:loaded?'block':'none'}}/>
  </div>
  <div className="raster-caption"><span><b>Variável:</b> {dataset?.variable_label||dataset?.name||'NASA'}</span><span><b>Região:</b> {region}</span><span><b>Período:</b> {period}</span></div>
  {range&&<div className="raster-legend"><span>{range.min} {range.unit||''}</span><i style={{background:range.palette?.length?`linear-gradient(90deg, ${range.palette.join(',')})`:undefined}}/><span>{range.max} {range.unit||''}</span></div>}
  <p className="chart-explain">Estatística: média temporal das imagens disponíveis no período. A paleta indica a magnitude do valor, não a significância estatística nem a tendência. A resolução espacial depende do produto NASA seleccionado.</p>
 </section>
}
function Lab({settings,updateSettings,region,variable,period,selectedDatasetId,periodMode,datasets,ran,setRan,t}:{settings:Settings;updateSettings:(n:Partial<Settings>)=>void;region:string;variable:string;period:string;selectedDatasetId:string;periodMode:'annual'|'five_year'|'decade';datasets:DatasetRecord[];ran:boolean;setRan:(v:boolean)=>void;t:any}){
 const [result,setResult]=useState<any|null>(null); const [busy,setBusy]=useState(false); const [error,setError]=useState(''); const [mapSrc,setMapSrc]=useState(''); const [elapsedSeconds,setElapsedSeconds]=useState(0); const requestLocked=useRef(false);
 useEffect(()=>{if(!busy)return;const timer=window.setInterval(()=>setElapsedSeconds(seconds=>seconds+1),1000);return()=>window.clearInterval(timer)},[busy]);
 const run=async()=>{if(requestLocked.current||busy)return;requestLocked.current=true;setElapsedSeconds(0);setBusy(true);setError('');setResult(null);setMapSrc('');setRan(false);try{const years=period.split(/[–-]/).map(x=>x.trim());const regionId=region==='Angola — todas as províncias'?'angola':region.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/,\s*angola$/,'').trim().replace(/\s+/g,'_');if(Number(years[1]||years[0])<Number(years[0])) throw new Error('O ano final deve ser igual ou posterior ao ano inicial.');setMapSrc(mapPreviewUrl({dataset_id:selectedDatasetId,region_id:regionId,start:years[0],end:years[1]||years[0]}));const data=await runAnalysis({dataset_id:selectedDatasetId,region_id:regionId,start:years[0],end:years[1]||years[0],scale:'annual',question:`Como evoluiu ${datasets.find(d=>d.id===selectedDatasetId)?.variable_label||variable} em ${region} entre ${years[0]} e ${years[1]||years[0]}?`,include_trend_map:false});setResult(data);setRan(true);}catch(e){setError(e instanceof Error?e.message:'Não foi possível executar a análise.');}finally{requestLocked.current=false;setBusy(false)}};
 const trend=result?.trend; const series=result?.series; const displaySeries=useMemo(()=>{if(!series?.values?.length)return {labels:[],values:[]};if(periodMode==='annual')return {labels:series.labels,values:series.values};const size=periodMode==='five_year'?5:10;const groups=new Map<number,{years:number[];values:number[]}>();series.labels.forEach((label:string,i:number)=>{const year=Number(label);const base=Math.floor(year/size)*size;const group=groups.get(base)||{years:[],values:[]};group.years.push(year);group.values.push(Number(series.values[i]));groups.set(base,group)});const keys=Array.from(groups.keys()).sort((a,b)=>a-b);return {labels:keys.map(k=>{const ys=groups.get(k)!.years;return `${Math.min(...ys)}–${Math.max(...ys)}`}),values:keys.map(k=>{const vs=groups.get(k)!.values;return vs.reduce((s,v)=>s+v,0)/vs.length})};},[series,periodMode]); const slope=trend?.sen?.slope_per_year; const p=trend?.mann_kendall?.p_value; const n=trend?.n_observations;
 const fmt=(v:any)=>typeof v==='number'?v.toLocaleString('pt-PT',{maximumFractionDigits:3}):'—';
 const stats=useMemo(()=>{const vals:number[]=(series?.values||[]).map((v:any)=>Number(v)).filter((v:number)=>Number.isFinite(v));if(!vals.length)return null;const sorted:number[]=[...vals].sort((a:number,b:number)=>a-b);const mean=vals.reduce((a:number,b:number)=>a+b,0)/vals.length;const median=sorted.length%2?sorted[(sorted.length-1)/2]:(sorted[sorted.length/2-1]+sorted[sorted.length/2])/2;const variance=vals.reduce((s:number,v:number)=>s+(v-mean)**2,0)/vals.length;const sd=Math.sqrt(variance);const first=vals[0],last=vals[vals.length-1];return {mean,median,min:sorted[0],max:sorted[sorted.length-1],range:sorted[sorted.length-1]-sorted[0],sd,cv:mean!==0?sd/Math.abs(mean)*100:null,absoluteChange:last-first,percentChange:first!==0?(last-first)/first*100:null,total:vals.reduce((a:number,b:number)=>a+b,0)};},[series]);
 return <><PageHead eyebrow="PASSO 02 · TREND LAB" title="Executa uma análise com dados reais." description="O botão consulta a API ligada ao Google Earth Engine. Os gráficos e indicadores só são preenchidos com a resposta recebida." action={<button className="button lime" onClick={run} disabled={busy} aria-live="polite"><Play size={15}/> {busy?'A consultar NASA…':t.run}</button>}/><div className="lab-toolbar"><div><span>REGIÃO</span><b>{region}</b></div><div><span>PERÍODO</span><b>{period}</b></div><div><span>FONTE</span><b>{datasets.find(d=>d.id===selectedDatasetId)?.name||'Fonte NASA'}</b></div><button className="button secondary" onClick={()=>{setResult(null);setError('');setRan(false)}}><RotateCcw size={15}/> Limpar</button></div>{error&&<p className="request-error" role="status">Estado do pedido: {error}</p>}{busy&&<div className="analysis-loading" role="status" aria-live="polite" aria-busy="true"><div className="analysis-loading-top"><div className="analysis-loading-head"><div className="analysis-spinner"><Activity size={19}/></div><div><b>A análise está em execução</b><span>Consulta remota ao NASA Earth Engine</span></div></div><div className="analysis-clock"><strong>{String(Math.floor(elapsedSeconds/60)).padStart(2,'0')}:{String(elapsedSeconds%60).padStart(2,'0')}</strong><span>tempo decorrido</span></div></div><div className="analysis-progress-track" aria-hidden="true"><i/></div><div className="analysis-stages"><div className="analysis-stage complete"><span>01</span><div><b>Pedido enviado</b><small>Parâmetros validados pela aplicação</small></div><Check size={15}/></div><div className="analysis-stage active"><span>02</span><div><b>Consulta ao serviço de dados</b><small>A aguardar a resposta do Earth Engine</small></div><i/></div><div className="analysis-stage pending"><span>03</span><div><b>Análise estatística</b><small>Será executada após a recepção da série</small></div></div><div className="analysis-stage pending"><span>04</span><div><b>Preparação dos resultados</b><small>Gráficos, indicadores e proveniência</small></div></div></div><p>O indicador é indeterminado: não representa uma percentagem fictícia. O tempo depende da dimensão da região, do período e da resposta do serviço NASA.</p></div>}<div className="visual-grid"><div className="panel"><PanelTitle icon={LineChart} title="Série temporal" tag={result?(periodMode==='annual'?'ANUAL':periodMode==='five_year'?'BLOCOS DE 5 ANOS':'DÉCADAS'):'SEM DADOS'}/><div className="visual-select"><label>Tipo de gráfico<select value={settings.chart} onChange={e=>updateSettings({chart:e.target.value as Settings['chart']})}><option>Linha</option><option>Área</option><option>Barras</option><option>Dispersão</option><option>Histograma</option><option>Circular</option><option disabled>Velas OHLC — requer dados próprios</option></select></label></div><Chart type={settings.chart} values={displaySeries.values} labels={displaySeries.labels} trendLine={periodMode==='annual'?(series?.trend_line||[]):[]} unit={result?.unit||''}/><div className="chart-axis"><span>{displaySeries.labels[0]||'—'}</span><span>Tempo →</span><span>{displaySeries.labels[displaySeries.labels.length-1]||'—'}</span></div><p className="panel-note">A tendência estatística (Mann–Kendall e Sen) é sempre calculada sobre a série anual original. Os blocos mostram médias dos valores anuais, apenas para comparação.</p></div></div>{mapSrc&&<MapPanel src={mapSrc} dataset={datasets.find(d=>d.id===selectedDatasetId)} region={region} period={period}/>}<div className="section-heading"><div><span className="eyebrow">RESULTADO {result?'RECEBIDO DA API':'AINDA NÃO EXECUTADO'}</span><h2>Resumo estatístico</h2></div><span className={result?'status-chip':'status-chip warning'}>{result?(trend?.significant?'Tendência significativa':'Sem tendência significativa'):'A aguardar análise'}</span></div><div className="result-grid"><Result label="Direção" value={trend?.direction_label||'—'} icon={TrendingUp}/><Result label="Declive de Sen" value={slope==null?'—':`${fmt(slope)} ${result?.unit||''}/ano`} icon={Activity}/><Result label="Valor-p (MK)" value={fmt(p)} icon={Gauge}/><Result label="Observações válidas" value={n==null?'—':String(n)} icon={Table2}/></div>{result&&stats&&<><div className="section-heading"><div><span className="eyebrow">ESTATÍSTICAS COMPLEMENTARES</span><h2>Mais dez leituras da série</h2></div></div><div className="result-grid extra-stats"><Result label="Média" value={fmt(stats.mean)} icon={BarChart3}/><Result label="Mediana" value={fmt(stats.median)} icon={Activity}/><Result label="Mínimo" value={fmt(stats.min)} icon={TrendingDown}/><Result label="Máximo" value={fmt(stats.max)} icon={TrendingUp}/><Result label="Amplitude" value={fmt(stats.range)} icon={Gauge}/><Result label="Desvio padrão" value={fmt(stats.sd)} icon={Activity}/><Result label="Coef. variação" value={stats.cv==null?'—':fmt(stats.cv)+'%'} icon={Gauge}/><Result label="Variação absoluta" value={fmt(stats.absoluteChange)} icon={ArrowRight}/><Result label="Variação relativa" value={stats.percentChange==null?'—':fmt(stats.percentChange)+'%'} icon={TrendingUp}/><Result label="Total da série" value={fmt(stats.total)} icon={Database}/></div><p className="panel-note">Unidade base: {result?.unit||'não indicada'} (excepto coeficiente de variação e variação percentual). Calculadas sobre os valores anuais recebidos. A soma só é interpretável para variáveis de acumulação; para variáveis de estado ou índices, deve ser lida como soma matemática.</p></>}{result&&<div className="interpret-grid"><div className="panel interpretation"><PanelTitle icon={ShieldCheck} title="Proveniência e interpretação"/><p>Fonte: <b>{result.dataset?.name||'NASA GPM IMERG'}</b>. Região: <b>{result.region?.name||region}</b>. Período analisado: <b>{result.period?.analyzed?.first}–{result.period?.analyzed?.last}</b>. Unidade: <b>{result.unit}</b>.</p><p>{trend?.reason||trend?.direction_label||'Resultado recebido.'} {trend?.significant?'O teste de Mann–Kendall indica significância ao nível configurado.':'O teste de Mann–Kendall não identificou tendência estatisticamente significativa ao nível configurado.'}</p>{(trend?.warnings||[]).map((w:string)=><p key={w}>{w}</p>)}</div><div className="panel limitation"><PanelTitle icon={BookOpen} title="Contexto do resultado"/><ul>{(result.limitations||[]).slice(0,5).map((w:string)=><li key={w}>{w}</li>)}</ul><p className="panel-note">O mapa raster não foi devolvido pelo modo Earth Engine de série regional.</p></div></div>}{result&&<div className="panel ml-insight"><PanelTitle icon={Sparkles} title="Aprendizagem automática" tag={result.ml_insight?.status==='ready'?'MODELO ACTIVO':result.ml_insight?.status==='learning'?'EM APRENDIZAGEM':'ESTADO INDISPONÍVEL'}/><div className="ml-learning-row"><div><b>{result.ml_insight?.status==='ready'?'Modelo adaptativo activo':result.ml_insight?.status==='learning'?'A construir memória de padrões':'Aprendizagem não disponível'}</b><span>{result.ml_insight?.training_examples??0} análises reais incorporadas neste modelo</span></div>{result.ml_insight?.anomaly_score!=null&&<strong>{fmt(result.ml_insight.anomaly_score)}</strong>}</div><p>{result.ml_insight?.message||'A análise estatística foi concluída; o estado do modelo não foi devolvido.'}</p><small>O modelo aprende assinaturas de variabilidade, declive relativo, dados em falta e valor-p. Não altera o cálculo científico nem prevê o futuro.</small></div>}{!result&&!error&&!busy&&<p className="lab-empty-hint">Os resultados serão apresentados aqui após a execução da análise.</p>}</>}
function Result({label,value,icon:Icon,tone}:{label:string;value:string;icon:any;tone?:string}){return <div className={'result '+(tone||'')}><Icon size={17}/><span>{label}</span><strong>{value}</strong><small>calculado na amostra</small></div>}
function Chart({type,values,labels,trendLine,unit}:{type:Settings['chart'];values:number[];labels:string[];trendLine:number[];unit?:string}){
 const [expanded,setExpanded]=useState(false); const [zoom,setZoom]=useState(1);
 const valid=values.map((v,i)=>({value:Number(v),label:labels[i]??String(i+1),index:i})).filter(d=>Number.isFinite(d.value));
 const palette=['#62d8dc','#40b6d0','#318bb4','#31508b','#30386f','#e45d5d','#edc85d','#70a982','#9b82c2'];
 const fmt=(v:number)=>v.toLocaleString('pt-PT',{maximumFractionDigits:2});
 if(!valid.length)return <div className="chart-box empty-chart" role="status"><p className="panel-note">O gráfico aparecerá aqui depois de uma análise real. Nenhuma série demonstrativa é utilizada.</p></div>;
 const W=760,H=340,L=78,R=22,T=24,B=54,PW=W-L-R,PH=H-T-B;
 const rawMin=Math.min(...valid.map(d=>d.value)),rawMax=Math.max(...valid.map(d=>d.value));
 const spread=rawMax-rawMin,pad=spread===0?Math.max(Math.abs(rawMax)*.08,1):spread*.12;
 const yMin=type==='Barras'?Math.min(0,rawMin):rawMin-pad,yMax=rawMax+pad,yRange=yMax-yMin||1;
 const x=(i:number)=>L+(valid.length===1?PW/2:(i/(valid.length-1))*PW), y=(v:number)=>T+(yMax-v)/yRange*PH;
 const ticks=Array.from({length:5},(_,i)=>yMin+(yRange*i/4)).reverse();
 const points=valid.map(d=>x(d.index)+','+y(d.value)).join(' ');
 const trend=trendLine.length===values.length?trendLine.map((v,i)=>Number.isFinite(Number(v))?x(i)+','+y(Number(v)):null).filter(Boolean).join(' '):'';
 const xTickIndexes=Array.from(new Set([0,...Array.from({length:Math.min(4,valid.length-1)},(_,i)=>Math.round((i+1)*(valid.length-1)/(Math.min(4,valid.length-1)))),valid.length-1]));
 const barWidth=Math.max(3,Math.min(28,PW/Math.max(valid.length,1)*.62));
 const total=valid.reduce((sum,d)=>sum+Math.max(0,d.value),0);
 const bins=Array.from({length:6},(_,i)=>({label:'Classe '+(i+1),count:0,from:rawMin+(rawMax-rawMin)*i/6,to:rawMin+(rawMax-rawMin)*(i+1)/6}));
 valid.forEach(d=>{const index=rawMax===rawMin?0:Math.min(5,Math.floor((d.value-rawMin)/(rawMax-rawMin)*6));bins[index].count++});
 const maxBin=Math.max(1,...bins.map(b=>b.count));
 let cumulative=0;
 return <div className={expanded?'chart-shell chart-expanded':'chart-shell'}>
  <div className="chart-meta"><span>{type==='Circular'?'PARTICIPAÇÃO RELATIVA':type==='Histograma'?'FREQUÊNCIA DOS VALORES':'VALOR OBSERVADO'}</span><span>{unit||'Unidade não indicada'}</span></div>
  <div className="chart-controls" aria-label="Controlos do gráfico">
   <button type="button" title="Reduzir" aria-label="Reduzir gráfico" onClick={()=>setZoom(v=>Math.max(.7,Number((v-.15).toFixed(2))))} disabled={zoom<=.7}><ZoomOut size={16}/></button>
   <span>{Math.round(zoom*100)}%</span>
   <button type="button" title="Ampliar" aria-label="Ampliar gráfico" onClick={()=>setZoom(v=>Math.min(1.75,Number((v+.15).toFixed(2))))} disabled={zoom>=1.75}><ZoomIn size={16}/></button>
   <button type="button" title={expanded?'Recolher gráfico':'Expandir gráfico'} aria-label={expanded?'Recolher gráfico':'Expandir gráfico'} onClick={()=>setExpanded(v=>!v)}>{expanded?<Minimize2 size={16}/>:<Expand size={16}/>}</button>
  </div>
  <div className="chart-box" style={{maxHeight:expanded?'calc(92vh - 125px)':undefined}}>
   {type==='Circular'?(total<=0||valid.some(d=>d.value<0)?<div className="empty-chart"><p className="panel-note">O gráfico circular só é adequado quando todos os valores são não negativos. Esta série não cumpre essa condição.</p></div>:<div className="pie-layout"><svg viewBox="0 0 360 300" role="img" aria-label="Gráfico circular com a participação relativa de cada observação" style={{width:(zoom*100)+'%',maxWidth:'100%',height:'auto'}}><circle cx="150" cy="145" r="92" fill="none" stroke="#edf1ee" strokeWidth="48"/>{valid.map((d,i)=>{const share=d.value/total,circ=2*Math.PI*92,offset=cumulative;cumulative+=share*circ;return <circle key={i} cx="150" cy="145" r="92" fill="none" stroke={palette[i%palette.length]} strokeWidth="48" strokeDasharray={share*circ+' '+(circ-share*circ)} strokeDashoffset={-offset} transform="rotate(-90 150 145)"><title>{d.label}: {(share*100).toFixed(1)}% do total</title></circle>})}<text x="150" y="140" textAnchor="middle" fontSize="14" fill="#53645b">Total</text><text x="150" y="162" textAnchor="middle" fontSize="16" fontWeight="700" fill="#263b2e">{fmt(total)}</text></svg><div className="pie-legend">{valid.map((d,i)=><span key={i}><i style={{background:palette[i%palette.length]}}/>{d.label} · {(d.value/total*100).toFixed(1)}%</span>)}</div><p className="chart-explain">Cada fatia representa a percentagem de um valor anual no total da série apresentada; não representa área geográfica.</p></div>):<svg viewBox={'0 0 '+W+' '+H} preserveAspectRatio="xMidYMid meet" role="img" aria-label={'Gráfico '+type.toLowerCase()+' da série temporal com '+valid.length+' observações, unidade '+(unit||'não indicada')} style={{width:(zoom*100)+'%',minWidth:zoom>1?'760px':undefined,height:'auto'}}>
    {type!=='Histograma'&&<>{ticks.map((tick,i)=><g key={i}><line x1={L} x2={W-R} y1={y(tick)} y2={y(tick)} stroke="#e5e9e7" strokeWidth="1"/><text x={L-12} y={y(tick)+4} textAnchor="end" className="chart-tick">{fmt(tick)}</text></g>)}<line x1={L} x2={W-R} y1={T+PH} y2={T+PH} stroke="#aeb8b2" strokeWidth="1.2"/></>}
    {type==='Barras'&&valid.map(d=><g key={d.index}><rect x={x(d.index)-barWidth/2} y={y(d.value)} width={barWidth} height={Math.max(1,y(0)-y(d.value))} rx="2" fill={palette[d.index%palette.length]} opacity=".92"><title>{d.label}: {fmt(d.value)} {unit}</title></rect></g>)}
    {type==='Linha'&&<><polyline points={points} fill="none" stroke="#40b6d0" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/>{trend&&<polyline points={trend} fill="none" stroke="#e45d5d" strokeWidth="2.5" strokeDasharray="7 5"/>}{valid.map(d=><circle key={d.index} cx={x(d.index)} cy={y(d.value)} r={valid.length>45?2.5:4} fill="#62d8dc" stroke="#278da2" strokeWidth="1.5"><title>{d.label}: {fmt(d.value)} {unit}</title></circle>)}</>}
    {type==='Área'&&<><polygon points={x(0)+','+(T+PH)+' '+points+' '+x(valid.length-1)+','+(T+PH)} fill="#62d8dc" opacity=".24"/><polyline points={points} fill="none" stroke="#40b6d0" strokeWidth="3"/>{valid.map(d=><circle key={d.index} cx={x(d.index)} cy={y(d.value)} r="3.5" fill="#31508b"><title>{d.label}: {fmt(d.value)} {unit}</title></circle>)}</>}
    {type==='Dispersão'&&valid.map(d=><circle key={d.index} cx={x(d.index)} cy={y(d.value)} r="5" fill="#31508b" stroke="#fff" strokeWidth="1.5"><title>{d.label}: {fmt(d.value)} {unit}</title></circle>)}
    {type==='Histograma'&&<>{bins.map((b,i)=>{const bw=PW/6-5,h=b.count/maxBin*PH;return <g key={i}><rect x={L+i*PW/6+2} y={T+PH-h} width={bw} height={h} rx="2" fill={palette[(i+1)%palette.length]}><title>{b.label}: {b.count} observações ({fmt(b.from)} a {fmt(b.to)})</title></rect><text x={L+i*PW/6+bw/2+2} y={T+PH+18} textAnchor="middle" className="chart-tick">{b.count}</text></g>})}<text x={L+PW/2} y={H-7} textAnchor="middle" className="chart-axis-title">Classes de valores · frequência</text></>}
    {type!=='Histograma'&&xTickIndexes.map(i=><g key={i}><line x1={x(i)} x2={x(i)} y1={T+PH} y2={T+PH+5} stroke="#aab9b0"/><text x={x(i)} y={H-19} textAnchor="middle" className="chart-tick">{valid[i]?.label}</text></g>)}
    {type!=='Histograma'&&<text x="17" y={T+PH/2} transform={'rotate(-90 17 '+(T+PH/2)+')'} textAnchor="middle" className="chart-axis-title">{unit||'Valor'}</text>}
    {type!=='Histograma'&&<text x={L+PW/2} y={H-2} textAnchor="middle" className="chart-axis-title">Ano</text>}
   </svg>}
  </div>
  {type!=='Circular'&&<div className="chart-legend"><span><i className="legend-observed"/> Dados observados</span>{trend&&(type==='Linha')&&<span><i className="legend-trend"/> Tendência estimada</span>}<small>{valid.length} observações · escala identificada</small></div>}
  {type==='Histograma'&&<p className="chart-explain">O histograma agrupa os valores observados em seis classes e mostra quantas observações caem em cada intervalo.</p>}
 </div>
}
